"""Compatibility helpers kept for historical sklearn-pandas APIs."""


class DataWrapper(object):
    """Wrap a DataFrame-like object with basic sequence semantics."""

    def __init__(self, df):
        self.df = df

    def __len__(self):
        return len(self.df)

    def __getitem__(self, key):
        return self.df.iloc[key]

