"""Custom transformers shipped with sklearn-pandas."""

import warnings

import numpy as np
import pandas as pd
from sklearn.base import BaseEstimator, TransformerMixin


def _get_mask(X, value):
    """
    Compute a boolean mask equivalent to ``X == value`` for null-like values.
    """

    if value == "NaN" or value is None or (
        isinstance(value, float) and np.isnan(value)
    ):
        return pd.isnull(X)

    return X == value


class NumericalTransformer(BaseEstimator, TransformerMixin):
    """
    Provides a small set of serializable numerical transforms.
    """

    SUPPORTED_FUNCTIONS = ["log", "log1p"]

    def __init__(self, func):
        warnings.warn(
            """
            NumericalTransformer will be deprecated in 3.0 version.
            Please use Sklearn.base.TransformerMixin to write
            customer transformers
            """,
            DeprecationWarning,
        )

        assert func in self.SUPPORTED_FUNCTIONS, (
            f"Only following func are supported: {self.SUPPORTED_FUNCTIONS}"
        )
        self.func = func
        self.__func = func
        super(NumericalTransformer, self).__init__()

    def fit(self, X, y=None):
        return self

    def _validate_numeric_input(self, X):
        try:
            values = np.asarray(X, dtype=float)
        except (TypeError, ValueError) as exc:
            raise ValueError(
                "NumericalTransformer only supports numeric inputs."
            ) from exc

        if not np.all(np.isfinite(values)):
            raise ValueError(
                "NumericalTransformer only supports finite numeric values."
            )

        if self.__func == "log" and np.any(values <= 0):
            raise ValueError(
                "NumericalTransformer('log') requires all values to be strictly positive."
            )

        if self.__func == "log1p" and np.any(values < -1):
            raise ValueError(
                "NumericalTransformer('log1p') requires all values to be greater than or equal to -1."
            )

        return values

    def _wrap_like_input(self, X, values):
        if isinstance(X, pd.DataFrame):
            return pd.DataFrame(values, columns=X.columns, index=X.index)
        if isinstance(X, pd.Series):
            return pd.Series(values, name=X.name, index=X.index)
        return values

    def transform(self, X, y=None):
        values = self._validate_numeric_input(X)

        if self.__func == "log1p":
            transformed = np.log1p(values)
        elif self.__func == "log":
            transformed = np.log(values)
        else:  # pragma: no cover
            raise ValueError(f"Invalid function name: {self.__func}")

        return self._wrap_like_input(X, transformed)

