"""Transformer-only pipeline helpers."""

from collections import Counter

from sklearn.pipeline import Pipeline

try:
    from sklearn.pipeline import _name_estimators
except ImportError:  # pragma: no cover
    def _name_estimators(estimators):
        """Fallback name generator mirroring sklearn.make_pipeline."""
        names = [type(estimator).__name__.lower() for estimator in estimators]
        counts = Counter(names)
        used = Counter()
        named_estimators = []
        for name, estimator in zip(names, estimators):
            if counts[name] > 1:
                used[name] += 1
                name = f"{name}-{used[name]}"
            named_estimators.append((name, estimator))
        return named_estimators


def _call_fit(fit_method, X, y=None, **kwargs):
    """
    Call a fit-style method with ``X`` and optional ``y``.

    This mirrors the historical sklearn-pandas behavior and retries without
    ``y`` when the target argument is not accepted.
    """

    try:
        return fit_method(X, y, **kwargs)
    except TypeError:
        return fit_method(X, **kwargs)


class TransformerPipeline(Pipeline):
    """
    Pipeline variant that expects every step to be a transformer.

    It keeps the lightweight sklearn-pandas semantics while remaining
    compatible with sklearn's ``Pipeline`` base class.
    """

    def __init__(self, steps):
        steps = list(steps)
        if not steps:
            raise ValueError("At least one pipeline step is required")

        names, estimators = zip(*steps)
        if len(dict(steps)) != len(steps):
            raise ValueError("Provided step names are not unique: %s" % (names,))

        for estimator in estimators:
            if (
                not (hasattr(estimator, "fit") or hasattr(estimator, "fit_transform"))
                or not hasattr(estimator, "transform")
            ):
                raise TypeError(
                    "All steps of the chain should be transforms and implement "
                    "fit and transform '%s' (type %s) doesn't)"
                    % (estimator, type(estimator))
                )

        if not hasattr(estimators[-1], "fit"):
            raise TypeError(
                "Last step of chain should implement fit '%s' (type %s) doesn't)"
                % (estimators[-1], type(estimators[-1]))
            )

        super().__init__(steps)

    def _pre_transform(self, X, y=None, **fit_params):
        """
        Fit and transform all but the last step of the pipeline.
        """

        fit_params_steps = {step: {} for step, _ in self.steps}
        for pname, pval in fit_params.items():
            step, param = pname.split("__", 1)
            fit_params_steps[step][param] = pval

        Xt = X
        for name, transform in self.steps[:-1]:
            if hasattr(transform, "fit_transform"):
                Xt = _call_fit(transform.fit_transform, Xt, y, **fit_params_steps[name])
            else:
                Xt = _call_fit(transform.fit, Xt, y, **fit_params_steps[name]).transform(
                    Xt
                )

        return Xt, fit_params_steps[self.steps[-1][0]]

    def fit(self, X, y=None, **fit_params):
        """
        Fit every step in the transformer chain.
        """

        Xt, fit_params = self._pre_transform(X, y, **fit_params)
        _call_fit(self.steps[-1][-1].fit, Xt, y, **fit_params)
        return self

    def fit_transform(self, X, y=None, **fit_params):
        """
        Fit every step and return the transformed result.
        """

        Xt, fit_params = self._pre_transform(X, y, **fit_params)
        last_step = self.steps[-1][-1]
        if hasattr(last_step, "fit_transform"):
            return _call_fit(last_step.fit_transform, Xt, y, **fit_params)

        return _call_fit(last_step.fit, Xt, y, **fit_params).transform(Xt)


def make_transformer_pipeline(*steps):
    """Construct a ``TransformerPipeline`` from unnamed estimators."""

    return TransformerPipeline(_name_estimators(steps))

